// Generated from site/demos/projects by build-demo-projects.mjs.
export const projects = {
  "list-detail": {
    "html.js": "const escapeHTML = value =>\n  String(value ?? '').replace(\n    /[&<>\"']/g,\n    character =>\n      ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;',\n      })[character],\n  );\n\nexport { escapeHTML };\n",
    "lesson-ui.js": "import { View, Region, CollectionView, MnObject } from 'marionette';\nimport { escapeHTML } from './html.js';\nimport { sections } from './source.js';\n\nconst Story = View.extend({\n  tagName: 'p',\n  className: 'story',\n  attributes: {\n    role: 'status',\n  },\n  template: ({ text }) => escapeHTML(text),\n});\nconst Explanation = View.extend({\n  tagName: 'section',\n  className: 'lesson-step',\n  template: ({ title, excerpts, observation, steps }) => `\n    <small>FOLLOW THE CONNECTION</small><h2>${escapeHTML(title)}</h2>\n    <ol class=\"cause-chain\">${steps.map(step => `<li>${escapeHTML(step)}</li>`).join('')}</ol>\n    ${excerpts\n      .map(excerpt =>\n        excerpt\n          ? `\n      <section class=\"source-excerpt\" data-source-file=\"${escapeHTML(excerpt.file)}\" data-source-symbol=\"${escapeHTML(excerpt.symbol)}\">\n        <button class=\"source-link\" data-file=\"${escapeHTML(excerpt.file)}\" data-symbol=\"${escapeHTML(excerpt.symbol)}\">${escapeHTML(excerpt.file)} · ${escapeHTML(excerpt.symbol)} ↗</button>\n        <small class=\"source-caption\">RUNNING SOURCE · LINES ${excerpt.line}–${excerpt.endLine}</small>\n        <div class=\"source-lines\"><pre><code>${excerpt.highlighted}</code></pre></div>\n      </section>`\n          : '<p class=\"source-missing\">This method was removed or renamed in the running source. Use the source files below to inspect your edit.</p>',\n      )\n      .join('')}\n    <p>${escapeHTML(observation)}</p>`,\n  ui: {\n    source: '.source-link',\n  },\n  events: {\n    'click @ui.source': 'onClickSource',\n  },\n  onClickSource({ delegateTarget }) {\n    sourceSelection = {\n      file: delegateTarget.dataset.file,\n      symbol: delegateTarget.dataset.symbol,\n      requestId: ++sourceRequest,\n    };\n  },\n});\nconst ObjectBoard = View.extend({\n  className: 'object-board',\n  template: ({ objects }) =>\n    objects\n      .map(\n        ([name, status, detail]) => `<section>\n    <h3>${escapeHTML(name)}</h3><strong>${escapeHTML(status)}</strong><p>${escapeHTML(detail)}</p></section>`,\n      )\n      .join(''),\n});\nconst Receipt = View.extend({\n  tagName: 'li',\n  createState() {\n    return {\n      observed: null,\n    };\n  },\n  templateContext() {\n    return this.getState();\n  },\n  template: ({ label, observed }) =>\n    `${observed === null ? '○' : observed ? '✓' : '✗'} ${escapeHTML(label)}`,\n  onRender() {\n    const observed = this.getState().observed;\n\n    if (observed === null) {\n      delete this.el.dataset.result;\n    } else {\n      this.el.dataset.result = observed ? 'pass' : 'fail';\n    }\n  },\n});\nconst Receipts = CollectionView.extend({\n  tagName: 'ol',\n});\nconst Lesson = View.extend({\n  className: 'lesson',\n  template: ({ icon, title, introduction, question }) => `<header class=\"hero\">\n    <span class=\"mascot\" aria-hidden=\"true\">${escapeHTML(icon)}</span>\n    <div><div class=\"kicker\">A SMALL EXPERIMENT</div><h1>${escapeHTML(title)}</h1></div></header>\n    ${question ? `<h2 class=\"lesson-question\">${escapeHTML(question)}</h2>` : ''}\n    <p class=\"lede\">${escapeHTML(introduction)}</p>\n    <div class=\"lesson-layout\">\n      <div class=\"lesson-play\"><div id=\"experiment\"></div><div class=\"retired-slot\"></div></div>\n      <aside class=\"lesson-explanation\" aria-label=\"Code and consequence\"><div class=\"explanation-slot\"></div><div class=\"story-slot\"></div></aside>\n    </div>\n    <details class=\"proof\" aria-label=\"Observed evidence\">\n      <summary>Inspector · objects &amp; checks</summary>\n      <p class=\"fine\">Peek under the floorboards. ○ means not tried yet; ✓ means an actual object passed the check.</p>\n      <div class=\"inspector-retired-slot\"></div><div class=\"board-slot\"></div><div class=\"receipts-slot\"></div>\n    </details>`,\n  regions: {\n    experiment: '#experiment',\n    story: '.story-slot',\n    retired: '.retired-slot',\n    retiredEvidence: '.inspector-retired-slot',\n    explanation: '.explanation-slot',\n    board: '.board-slot',\n    receipts: '.receipts-slot',\n  },\n  onRender() {\n    this.showChildView('receipts', new Receipts());\n    for (const { id, label } of this.model.evidence) {\n      const receipt = new Receipt({\n        model: {\n          label,\n        },\n      });\n\n      receiptViews.set(id, receipt);\n      this.getChildView('receipts').addChildView(receipt);\n    }\n  },\n});\nconst lifecycle = [];\nconst checks = new Map();\nconst views = [];\nconst receiptViews = new Map();\nlet lifecycleDropped = 0;\nexport let lesson;\nlet sourceSelection,\n  sourceRequest = 0;\n\n// Demo instrumentation only: these methods observe ownership; they do not create it.\nconst observedRegions = new Map();\nconst objectGroups = new Map();\nconst demoInspector = {\n  observeView(name, view) {\n    views.push({\n      name,\n      view,\n    });\n    for (const event of ['render', 'attach', 'detach', 'before:destroy', 'destroy']) {\n      view.on(event, () => {\n        lifecycle.push(name + ':' + event);\n        if (lifecycle.length > 40) {\n          lifecycle.shift();\n          lifecycleDropped++;\n        }\n      });\n    }\n\n    return view;\n  },\n  check(id, observed) {\n    checks.set(id, {\n      id,\n      expected: true,\n      observed: Boolean(observed),\n    });\n    const receipt = receiptViews.get(id);\n\n    if (receipt) {\n      receipt.getState().observed = Boolean(observed);\n      receipt.render();\n    }\n  },\n  observeRegion(name, region) {\n    observedRegions.set(name, region);\n  },\n  showRetired(view) {\n    lesson.showChildView('retiredEvidence', view);\n  },\n  updateObjects(name, objects) {\n    objectGroups.set(name, objects);\n    lesson.showChildView(\n      'board',\n      new ObjectBoard({\n        model: {\n          objects: [...objectGroups.values()].flat(),\n        },\n      }),\n    );\n  },\n  reset() {\n    lesson.getRegion('retiredEvidence').empty();\n    objectGroups.clear();\n    lesson.getRegion('board').empty();\n    checks.clear();\n    views.length = lifecycle.length = 0;\n    lifecycleDropped = 0;\n    observedRegions.clear();\n    this.observeRegion('root', lesson.getRegion('experiment'));\n    for (const receipt of receiptViews.values()) {\n      receipt.getState().observed = null;\n      receipt.render();\n    }\n  },\n  inspect() {\n    return {\n      sourceSelection,\n      checks: [...checks.values()],\n      lifecycle,\n      lifecycleDropped,\n      views,\n      regions: [...observedRegions].map(([name, region]) => ({\n        name,\n        region,\n      })),\n    };\n  },\n};\n\nfunction story(text) {\n  lesson.showChildView(\n    'story',\n    new Story({\n      model: {\n        text,\n      },\n    }),\n  );\n}\nfunction explain(title, references, observation, steps = []) {\n  const excerpts = [references].flat().map(({ file, symbol }) => sections[file]?.[symbol] || null);\n  lesson.showChildView(\n    'explanation',\n    new Explanation({\n      model: {\n        title,\n        excerpts,\n        observation,\n        steps,\n      },\n    }),\n  );\n}\nfunction stage({ icon, title, question, introduction, instruction, evidence }) {\n  lesson = new Lesson({\n    model: {\n      icon,\n      title,\n      introduction,\n      question,\n      evidence,\n    },\n  });\n  new Region({\n    el: '#app',\n  }).show(lesson);\n  if (instruction) story(instruction);\n}\nfunction inspectRecipe() {\n  return demoInspector.inspect();\n}\n// The controller owns subscriptions and teaching UI. App Views never import it.\nconst LessonController = MnObject.extend({\n  initialize({ configuration, ViewClass, viewOptions = {} }) {\n    stage(configuration);\n    this.region = lesson.getRegion('experiment');\n    this.ViewClass = ViewClass;\n    this.viewOptions = viewOptions;\n    this.showApp();\n  },\n  showApp() {\n    this.view = new this.ViewClass(this.viewOptions);\n    demoInspector.observeRegion('root', this.region);\n    demoInspector.observeView('shell', this.view);\n    this.observe(this.view);\n    this.region.show(this.view);\n    this.ready?.(this.view);\n  },\n  reset() {\n    this.region.empty();\n    this.stopListening();\n    demoInspector.reset();\n    this.showApp();\n  },\n  onBeforeDestroy() {\n    this.region.empty();\n  },\n});\nexport { LessonController, demoInspector, story, explain, inspectRecipe };\n",
    "app.js": "import { View } from 'marionette';\nimport { DataApi } from '@mnjs/data';\nimport { TodoList, TodoFooter } from './todo-views.js';\nimport { PlanningNotes } from './planning-notes.js';\n\n// Start here: Todos composes the app with three named Regions.\n// todo-views.js owns Models and rows; planning-notes.js owns the draft.\nconst Todos = View.extend({\n  template: () => `\n    <section class=\"todoapp\" aria-label=\"Todo list\">\n      <h2 class=\"todos-heading\">todos</h2>\n      <label class=\"sr-only\" for=\"new-todo\">What needs to be done?</label>\n      <input id=\"new-todo\" placeholder=\"What needs to be done?\" autocomplete=\"off\">\n      <section class=\"todo-main\">\n        <input id=\"toggle-all\" type=\"checkbox\" aria-label=\"Mark all as complete\">\n        <label for=\"toggle-all\" class=\"toggle-all-label\" title=\"Mark all as complete\">❯</label>\n        <div class=\"list\"></div>\n      </section>\n      <div class=\"footer-slot\"></div>\n    </section>\n    <p class=\"todo-instructions\">Double-click to edit a todo · Enter saves · Escape cancels</p>\n    <p class=\"todo-instructions\">Made with Marionette. Stored in memory for this run.</p>\n    <details class=\"notes-experiment\"><summary>Side experiment: keep a draft while the list changes</summary>\n    <p class=\"fine\">Two Regions, two independent Views. This exercise adds or removes a test task while you stay in the notes input.</p>\n    <div class=\"detail\"></div>\n    <button id=\"change-list\">Add / remove a test task</button></details>\n  `,\n  regions: {\n    list: '.list',\n    notes: '.detail',\n    footer: '.footer-slot',\n  },\n  ui: {\n    input: '#new-todo',\n    toggleAll: '#toggle-all',\n    main: '.todo-main',\n    change: '#change-list',\n  },\n  events: {\n    'keydown @ui.input': 'onKeydownNewTodo',\n    'change @ui.toggleAll': 'onChangeToggleAll',\n  },\n  triggers: {\n    'click @ui.change': 'click:neighbor',\n  },\n  childViewEvents: {\n    'press:enter': 'changeNeighbor',\n    'select:filter': 'onSelectFilter',\n    'click:clearCompleted': 'onClickClearCompleted',\n  },\n  collectionEvents: {\n    update: 'refresh',\n    reset: 'refresh',\n    'change:completed': 'refresh',\n  },\n  onClickNeighbor() {\n    this.changeNeighbor();\n  },\n  onRender() {\n    this.filter = 'all';\n    this.list = new TodoList({\n      collection: this.collection,\n    });\n    this.notes = new PlanningNotes();\n    this.showChildView('list', this.list);\n    this.showChildView('notes', this.notes);\n    this.showChildView('footer', new TodoFooter());\n    this.refresh();\n  },\n  onAttach() {\n    this.getUI('input')[0].focus();\n    this.routeListener = this.onChangeRoute.bind(this);\n    window.addEventListener('hashchange', this.routeListener);\n    this.onChangeRoute();\n  },\n  onChangeRoute() {\n    this.filter =\n      location.hash === '#/active'\n        ? 'active'\n        : location.hash === '#/completed'\n          ? 'completed'\n          : 'all';\n    this.refresh();\n  },\n  onBeforeDetach() {\n    window.removeEventListener('hashchange', this.routeListener);\n  },\n  onBeforeDestroy() {\n    window.removeEventListener('hashchange', this.routeListener);\n    this.collection.destroy();\n  },\n  onKeydownNewTodo(event) {\n    if (event.key !== 'Enter') {\n      return;\n    }\n    event.preventDefault();\n    const input = event.delegateTarget;\n    if (!input.value.trim()) {\n      return;\n    }\n    this.addTodo(input.value.trim());\n    input.value = '';\n  },\n  addTodo(title) {\n    return this.collection.add({\n      title,\n    });\n  },\n  onSelectFilter(filter) {\n    this.filter = filter;\n    location.hash = filter === 'all' ? '#/' : '#/' + filter;\n    this.refresh();\n    this.triggerMethod('change:filter', filter);\n  },\n  onChangeToggleAll() {\n    const completed = this.collection.remaining() > 0;\n    this.collection.forEach(todo => todo.set('completed', completed));\n  },\n  onClickClearCompleted() {\n    this.collection.remove(this.collection.completed());\n  },\n  refresh() {\n    const count = this.collection.length;\n    const remaining = this.collection.remaining();\n    this.getUI('toggleAll')[0].checked = count > 0 && remaining === 0;\n    this.getUI('toggleAll')[0].disabled = !count;\n    this.getUI('main')[0].hidden = !count;\n    this.getChildView('footer').getState().set({\n      count,\n      remaining,\n      filter: this.filter,\n    });\n    // CollectionView owns which children are attached. The notes Region stays put.\n    this.list.setFilter(item =>\n      this.filter === 'active'\n        ? !item.model.get('completed')\n        : this.filter === 'completed'\n          ? item.model.get('completed')\n          : true,\n    );\n  },\n  changeNeighbor() {\n    if (this.neighbor && this.collection.get(this.neighbor)) {\n      this.collection.remove(this.neighbor);\n      this.neighbor = null;\n    } else {\n      this.neighbor = this.addTodo('Take a highly strategic biscuit break');\n    }\n    this.triggerMethod('change:neighbor');\n  },\n});\nTodos.setDataApi(DataApi);\n\nexport { Todos };\n",
    "lesson.js": "import { LessonController, demoInspector, explain, story } from './lesson-ui.js';\n\nconst at = symbol => ({ file: 'app.js', symbol });\nconst row = symbol => ({ file: 'todo-views.js', symbol });\n\nexport const TodoLesson = LessonController.extend({\n  observe(view) {\n    this.listenTo(view, 'render', () => {\n      this.listenTo(view.list, 'add:child', (list, child) => this.trackChild(child));\n      demoInspector.observeView('list', view.list);\n      demoInspector.observeView('notes', view.notes);\n      demoInspector.observeRegion('todos.list', view.getRegion('list'));\n      demoInspector.observeRegion('todos.notes', view.getRegion('notes'));\n    });\n    this.listenTo(view, 'change:neighbor', this.onChangeNeighbor);\n    this.listenTo(view.collection, 'add', () => {\n      this.trackRows();\n      explain(\n        'A Model becomes a row.',\n        [at('Todos.addTodo'), row('TodoList.childView')],\n        'The Collection stores the task. CollectionView creates a TodoItem for it—no manual row insertion.',\n        ['You submitted a task.', 'Todos added its Model.', 'CollectionView attached its row.'],\n      );\n    });\n    this.listenTo(view.collection, 'remove', model => {\n      this.children.delete(model);\n      explain(\n        'Removing data removes its owned row.',\n        row('TodoList.onClickRemove'),\n        'The child emits click:remove. TodoList removes its Model, and CollectionView destroys that child.',\n        [\n          'The row emitted an event.',\n          'Its owner removed the Model.',\n          'The child View was destroyed.',\n        ],\n      );\n    });\n    this.listenTo(view.collection, 'change:completed', () =>\n      explain(\n        'The row and its count follow the Model.',\n        [row('TodoItem.onChangeCompleted'), row('TodoItem.modelEvents')],\n        'A checkbox changes its Model. The row observes that change; the parent updates its footer and filter. The notes View stays intact.',\n      ),\n    );\n    this.listenTo(view.collection, 'change:title', () =>\n      explain(\n        'An edit reaches the Model.',\n        row('TodoItem.save'),\n        'The row saves its draft into its Model. The same row View renders the new title.',\n      ),\n    );\n    this.listenTo(view, 'change:filter', () =>\n      explain(\n        'Filtering changes which rows are attached.',\n        at('Todos.refresh'),\n        'CollectionView applies the filter. It does not rebuild the notes Region.',\n      ),\n    );\n  },\n  ready(view) {\n    this.children = new Map();\n    this.trackRows();\n    this.input = view.notes.getUI('draft')[0];\n    this.retained = view.list.children.find(() => true);\n    this.element = this.retained?.el;\n    explain(\n      'Start with a task, a Model, and a row.',\n      [at('Todos.addTodo'), row('TodoList.childView')],\n      'Add a todo, complete it, then delete it. Each action reveals the actual method running here. The optional draft exercise below explores independent Regions.',\n      ['Add a Model.', 'Interact with its child View.', 'Follow the event back to its owner.'],\n    );\n  },\n  trackRows() {\n    this.children ||= new Map();\n    this.view.collection.forEach(model => {\n      const child = this.view.list?.children.findByModel(model);\n      if (child) {\n        this.trackChild(child);\n      }\n    });\n  },\n  trackChild(child) {\n    this.children ||= new Map();\n    if (this.children.get(child.model) === child) {\n      return;\n    }\n    this.children.set(child.model, child);\n    this.listenTo(child, 'destroy', () =>\n      demoInspector.check('removed-child-destroyed', child.isDestroyed()),\n    );\n  },\n  onChangeNeighbor() {\n    const view = this.view;\n    demoInspector.check('input-identity', view.notes.getUI('draft')[0] === this.input);\n    demoInspector.check('draft-preserved', this.input.value === view.notes.getState().draft);\n    demoInspector.check('focus-preserved', document.activeElement === this.input);\n    if (this.retained) {\n      demoInspector.check(\n        'child-identity',\n        view.list.children.findByCid(this.retained.cid) === this.retained &&\n          this.retained.el === this.element,\n      );\n    }\n    explain(\n      'The neighboring row changed. Your input stayed put.',\n      at('Todos.changeNeighbor'),\n      'The list and notes have separate Regions. This check compares the actual input and row objects; it is not a visual imitation.',\n      [\n        'The Collection changed.',\n        'CollectionView updated its child.',\n        'The notes input and cursor stayed alive.',\n      ],\n    );\n    story('Same draft. Same input. Your master plan has survived a biscuit-related interruption.');\n  },\n});\n",
    "main.js": "import { Todos } from './app.js';\nimport { TodoLesson } from './lesson.js';\nimport { TodoCollection } from './todo-views.js';\nexport { inspectRecipe } from './lesson-ui.js';\n\nconst controller = new TodoLesson({\n  ViewClass: Todos,\n  viewOptions: { collection: new TodoCollection([{ title: 'Finish one small thing' }]) },\n  configuration: {\n    icon: '☑',\n    title: 'TodoMVC, one View at a time',\n    question: 'How does a Model become a row you can interact with?',\n    introduction:\n      'Add a task, complete it, then remove it. Follow the data, child events, and Views that make a small app work. Your world domination plans can wait in the optional scratchpad.',\n    instruction:\n      'First: add a todo above. Then complete or delete it and follow the code beside the app. This demo keeps data only for this run.',\n    evidence: [\n      {\n        id: 'child-identity',\n        label: 'The original todo is the same View and DOM element.',\n      },\n      {\n        id: 'input-identity',\n        label: 'Your editor is the same input, not a convincing replacement.',\n      },\n      {\n        id: 'draft-preserved',\n        label: 'Every typed character survived the list change.',\n      },\n      {\n        id: 'focus-preserved',\n        label: 'The keyboard focus stayed in your draft.',\n      },\n      {\n        id: 'removed-child-destroyed',\n        label: 'The removed todo View was destroyed. One less thing.',\n      },\n    ],\n  },\n});\n\nexport const region = controller.region;\n",
    "planning-notes.js": "import { View } from 'marionette';\n\nconst PlanningNotes = View.extend({\n  createState() {\n    return {\n      draft: '',\n    };\n  },\n  template: () => `\n    <label for=\"draft\">Your unsaved master plan</label>\n    <input id=\"draft\" placeholder=\"First, find the list. Then, a biscuit.\" autocomplete=\"off\">\n    <p class=\"fine\">Experiment shortcut: Enter adds/removes a test task in the other Region. Keep typing to check that this input and its cursor survived.</p>\n  `,\n  ui: {\n    draft: '#draft',\n  },\n  events: {\n    'input @ui.draft': 'onInputDraft',\n    'keydown @ui.draft': 'onKeydownDraft',\n  },\n  onInputDraft({ delegateTarget }) {\n    this.getState().draft = delegateTarget.value;\n  },\n  onKeydownDraft(event) {\n    if (event.key !== 'Enter') {\n      return;\n    }\n    event.preventDefault();\n    this.triggerMethod('press:enter');\n  },\n});\n\nexport { PlanningNotes };\n",
    "todo-views.js": "import { View, CollectionView } from 'marionette';\nimport { Model, Collection, DataApi, StateApi } from '@mnjs/data';\nimport { escapeHTML } from './html.js';\n\n// TodoMVC-style editing with independent Marionette owners.\n// Model, Collection and DataApi are supplied by the pinned @mnjs/data bundle.\n// @mnjs/data owns the todos; CollectionView observes membership and each\n// TodoItem observes its Model. Local editing state belongs to the row View.\nconst Todo = Model.extend({\n  defaults: {\n    title: '',\n    completed: false,\n  },\n});\nconst TodoCollection = Collection.extend({\n  model: Todo,\n  remaining() {\n    return this.models.filter(todo => !todo.get('completed')).length;\n  },\n  completed() {\n    return this.models.filter(todo => todo.get('completed'));\n  },\n});\nconst TodoItem = View.extend({\n  tagName: 'li',\n  className: 'todo-item',\n  createState() {\n    return {\n      editing: false,\n    };\n  },\n  modelEvents: {\n    change: 'render',\n  },\n  templateContext() {\n    return this.getState();\n  },\n  template: ({ title, completed, editing }) => `\n    <input class=\"toggle\" type=\"checkbox\" aria-label=\"Complete todo\" ${completed ? 'checked' : ''}>\n    <label class=\"todo-title\" tabindex=\"0\" role=\"button\" title=\"Double-click to edit\">${escapeHTML(title)}</label>\n    <button class=\"delete-todo\" aria-label=\"Delete todo\">×</button>\n    <input class=\"edit\" aria-label=\"Edit todo title\" value=\"${escapeHTML(title)}\" ${editing ? '' : 'hidden'}>`,\n  ui: {\n    toggle: '.toggle',\n    title: '.todo-title',\n    edit: '.edit',\n    remove: '.delete-todo',\n  },\n  events: {\n    'change @ui.toggle': 'onChangeCompleted',\n    'keydown @ui.title': 'onKeydownTitle',\n    'keydown @ui.edit': 'onKeydownEdit',\n    'focusout @ui.edit': 'onFocusoutEdit',\n  },\n  triggers: {\n    'dblclick @ui.title': 'dblclick:title',\n    'click @ui.remove': 'click:remove',\n  },\n  onDblclickTitle() {\n    this.edit();\n  },\n  onFocusoutEdit() {\n    this.save();\n  },\n  onRender() {\n    const { editing } = this.getState();\n    const completed = this.model.get('completed');\n    this.el.classList.toggle('completed', completed);\n    this.el.classList.toggle('editing', editing);\n    if (editing) {\n      const [input] = this.getUI('edit');\n      input.focus();\n      input.select();\n    }\n  },\n  onKeydownTitle(event) {\n    if (event.key === 'Enter') {\n      event.preventDefault();\n      this.edit();\n    }\n  },\n  onChangeCompleted() {\n    const focused = this.getUI('toggle')[0] === document.activeElement;\n    this.model.set('completed', !this.model.get('completed'));\n    if (focused) {\n      this.getUI('toggle')[0].focus({\n        preventScroll: true,\n      });\n    }\n  },\n  edit() {\n    this.getState().editing = true;\n    this.render();\n  },\n  onKeydownEdit(event) {\n    if (event.key === 'Enter') {\n      event.preventDefault();\n      this.save();\n    }\n    if (event.key === 'Escape') {\n      event.preventDefault();\n      this.endEdit();\n    }\n  },\n  save() {\n    if (!this.getState().editing) {\n      return;\n    }\n    const title = this.getUI('edit')[0].value.trim();\n    if (!title) {\n      this.getState().editing = false;\n      this.triggerMethod('submit:emptyTitle', this.model);\n      return;\n    }\n    if (title === this.model.get('title')) {\n      this.endEdit();\n      return;\n    }\n    this.getState().editing = false;\n    this.model.set('title', title);\n  },\n  endEdit() {\n    this.getState().editing = false;\n    this.render();\n  },\n});\nTodoItem.setDataApi(DataApi);\nconst TodoList = CollectionView.extend({\n  tagName: 'ul',\n  childView: TodoItem,\n  childViewEvents: {\n    'click:remove': 'onClickRemove',\n    'submit:emptyTitle': 'onSubmitEmptyTitle',\n  },\n  onClickRemove(view) {\n    this.collection.remove(view.model);\n  },\n  onSubmitEmptyTitle(model) {\n    this.collection.remove(model);\n  },\n});\nTodoList.setDataApi(DataApi);\nconst TodoFooter = View.extend({\n  createState() {\n    return new Model({ count: 0, remaining: 0, filter: 'all' });\n  },\n  stateEvents: {\n    change: 'render',\n  },\n  templateContext() {\n    return this.getState().toObject();\n  },\n  template: ({ count, remaining, filter }) => `<footer class=\"todo-footer\" ${count ? '' : 'hidden'}>\n    <span id=\"todo-count\" role=\"status\"><strong>${remaining}</strong> item${remaining === 1 ? '' : 's'} left</span>\n    <nav aria-label=\"Filter todos\">${['all', 'active', 'completed'].map(name => `<a href=\"#/${name === 'all' ? '' : name}\" data-filter=\"${name}\" ${filter === name ? 'aria-current=\"page\"' : ''}>${name[0].toUpperCase() + name.slice(1)}</a>`).join('')}</nav>\n    <button id=\"clear-completed\" ${remaining === count ? 'hidden' : ''}>Clear completed</button></footer>`,\n  ui: {\n    filters: '[data-filter]',\n    clear: '#clear-completed',\n  },\n  events: {\n    'click @ui.filters': 'onClickFilter',\n  },\n  triggers: {\n    'click @ui.clear': 'click:clearCompleted',\n  },\n  onClickFilter(event) {\n    event.preventDefault();\n    this.triggerMethod('select:filter', event.delegateTarget.dataset.filter);\n  },\n});\nTodoFooter.setStateApi(StateApi);\n\nexport { TodoCollection, TodoItem, TodoList, TodoFooter };\n"
  },
  "owned-widget": {
    "html.js": "const escapeHTML = value =>\n  String(value ?? '').replace(\n    /[&<>\"']/g,\n    character =>\n      ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;',\n      })[character],\n  );\n\nexport { escapeHTML };\n",
    "lesson-ui.js": "import { View, Region, CollectionView, MnObject } from 'marionette';\nimport { escapeHTML } from './html.js';\nimport { sections } from './source.js';\n\nconst Story = View.extend({\n  tagName: 'p',\n  className: 'story',\n  attributes: {\n    role: 'status',\n  },\n  template: ({ text }) => escapeHTML(text),\n});\nconst Explanation = View.extend({\n  tagName: 'section',\n  className: 'lesson-step',\n  template: ({ title, excerpts, observation, steps }) => `\n    <small>FOLLOW THE CONNECTION</small><h2>${escapeHTML(title)}</h2>\n    <ol class=\"cause-chain\">${steps.map(step => `<li>${escapeHTML(step)}</li>`).join('')}</ol>\n    ${excerpts\n      .map(excerpt =>\n        excerpt\n          ? `\n      <section class=\"source-excerpt\" data-source-file=\"${escapeHTML(excerpt.file)}\" data-source-symbol=\"${escapeHTML(excerpt.symbol)}\">\n        <button class=\"source-link\" data-file=\"${escapeHTML(excerpt.file)}\" data-symbol=\"${escapeHTML(excerpt.symbol)}\">${escapeHTML(excerpt.file)} · ${escapeHTML(excerpt.symbol)} ↗</button>\n        <small class=\"source-caption\">RUNNING SOURCE · LINES ${excerpt.line}–${excerpt.endLine}</small>\n        <div class=\"source-lines\"><pre><code>${excerpt.highlighted}</code></pre></div>\n      </section>`\n          : '<p class=\"source-missing\">This method was removed or renamed in the running source. Use the source files below to inspect your edit.</p>',\n      )\n      .join('')}\n    <p>${escapeHTML(observation)}</p>`,\n  ui: {\n    source: '.source-link',\n  },\n  events: {\n    'click @ui.source': 'onClickSource',\n  },\n  onClickSource({ delegateTarget }) {\n    sourceSelection = {\n      file: delegateTarget.dataset.file,\n      symbol: delegateTarget.dataset.symbol,\n      requestId: ++sourceRequest,\n    };\n  },\n});\nconst ObjectBoard = View.extend({\n  className: 'object-board',\n  template: ({ objects }) =>\n    objects\n      .map(\n        ([name, status, detail]) => `<section>\n    <h3>${escapeHTML(name)}</h3><strong>${escapeHTML(status)}</strong><p>${escapeHTML(detail)}</p></section>`,\n      )\n      .join(''),\n});\nconst Receipt = View.extend({\n  tagName: 'li',\n  createState() {\n    return {\n      observed: null,\n    };\n  },\n  templateContext() {\n    return this.getState();\n  },\n  template: ({ label, observed }) =>\n    `${observed === null ? '○' : observed ? '✓' : '✗'} ${escapeHTML(label)}`,\n  onRender() {\n    const observed = this.getState().observed;\n\n    if (observed === null) {\n      delete this.el.dataset.result;\n    } else {\n      this.el.dataset.result = observed ? 'pass' : 'fail';\n    }\n  },\n});\nconst Receipts = CollectionView.extend({\n  tagName: 'ol',\n});\nconst Lesson = View.extend({\n  className: 'lesson',\n  template: ({ icon, title, introduction, question }) => `<header class=\"hero\">\n    <span class=\"mascot\" aria-hidden=\"true\">${escapeHTML(icon)}</span>\n    <div><div class=\"kicker\">A SMALL EXPERIMENT</div><h1>${escapeHTML(title)}</h1></div></header>\n    ${question ? `<h2 class=\"lesson-question\">${escapeHTML(question)}</h2>` : ''}\n    <p class=\"lede\">${escapeHTML(introduction)}</p>\n    <div class=\"lesson-layout\">\n      <div class=\"lesson-play\"><div id=\"experiment\"></div><div class=\"retired-slot\"></div></div>\n      <aside class=\"lesson-explanation\" aria-label=\"Code and consequence\"><div class=\"explanation-slot\"></div><div class=\"story-slot\"></div></aside>\n    </div>\n    <details class=\"proof\" aria-label=\"Observed evidence\">\n      <summary>Inspector · objects &amp; checks</summary>\n      <p class=\"fine\">Peek under the floorboards. ○ means not tried yet; ✓ means an actual object passed the check.</p>\n      <div class=\"inspector-retired-slot\"></div><div class=\"board-slot\"></div><div class=\"receipts-slot\"></div>\n    </details>`,\n  regions: {\n    experiment: '#experiment',\n    story: '.story-slot',\n    retired: '.retired-slot',\n    retiredEvidence: '.inspector-retired-slot',\n    explanation: '.explanation-slot',\n    board: '.board-slot',\n    receipts: '.receipts-slot',\n  },\n  onRender() {\n    this.showChildView('receipts', new Receipts());\n    for (const { id, label } of this.model.evidence) {\n      const receipt = new Receipt({\n        model: {\n          label,\n        },\n      });\n\n      receiptViews.set(id, receipt);\n      this.getChildView('receipts').addChildView(receipt);\n    }\n  },\n});\nconst lifecycle = [];\nconst checks = new Map();\nconst views = [];\nconst receiptViews = new Map();\nlet lifecycleDropped = 0;\nexport let lesson;\nlet sourceSelection,\n  sourceRequest = 0;\n\n// Demo instrumentation only: these methods observe ownership; they do not create it.\nconst observedRegions = new Map();\nconst objectGroups = new Map();\nconst demoInspector = {\n  observeView(name, view) {\n    views.push({\n      name,\n      view,\n    });\n    for (const event of ['render', 'attach', 'detach', 'before:destroy', 'destroy']) {\n      view.on(event, () => {\n        lifecycle.push(name + ':' + event);\n        if (lifecycle.length > 40) {\n          lifecycle.shift();\n          lifecycleDropped++;\n        }\n      });\n    }\n\n    return view;\n  },\n  check(id, observed) {\n    checks.set(id, {\n      id,\n      expected: true,\n      observed: Boolean(observed),\n    });\n    const receipt = receiptViews.get(id);\n\n    if (receipt) {\n      receipt.getState().observed = Boolean(observed);\n      receipt.render();\n    }\n  },\n  observeRegion(name, region) {\n    observedRegions.set(name, region);\n  },\n  showRetired(view) {\n    lesson.showChildView('retiredEvidence', view);\n  },\n  updateObjects(name, objects) {\n    objectGroups.set(name, objects);\n    lesson.showChildView(\n      'board',\n      new ObjectBoard({\n        model: {\n          objects: [...objectGroups.values()].flat(),\n        },\n      }),\n    );\n  },\n  reset() {\n    lesson.getRegion('retiredEvidence').empty();\n    objectGroups.clear();\n    lesson.getRegion('board').empty();\n    checks.clear();\n    views.length = lifecycle.length = 0;\n    lifecycleDropped = 0;\n    observedRegions.clear();\n    this.observeRegion('root', lesson.getRegion('experiment'));\n    for (const receipt of receiptViews.values()) {\n      receipt.getState().observed = null;\n      receipt.render();\n    }\n  },\n  inspect() {\n    return {\n      sourceSelection,\n      checks: [...checks.values()],\n      lifecycle,\n      lifecycleDropped,\n      views,\n      regions: [...observedRegions].map(([name, region]) => ({\n        name,\n        region,\n      })),\n    };\n  },\n};\n\nfunction story(text) {\n  lesson.showChildView(\n    'story',\n    new Story({\n      model: {\n        text,\n      },\n    }),\n  );\n}\nfunction explain(title, references, observation, steps = []) {\n  const excerpts = [references].flat().map(({ file, symbol }) => sections[file]?.[symbol] || null);\n  lesson.showChildView(\n    'explanation',\n    new Explanation({\n      model: {\n        title,\n        excerpts,\n        observation,\n        steps,\n      },\n    }),\n  );\n}\nfunction stage({ icon, title, question, introduction, instruction, evidence }) {\n  lesson = new Lesson({\n    model: {\n      icon,\n      title,\n      introduction,\n      question,\n      evidence,\n    },\n  });\n  new Region({\n    el: '#app',\n  }).show(lesson);\n  if (instruction) story(instruction);\n}\nfunction inspectRecipe() {\n  return demoInspector.inspect();\n}\n// The controller owns subscriptions and teaching UI. App Views never import it.\nconst LessonController = MnObject.extend({\n  initialize({ configuration, ViewClass, viewOptions = {} }) {\n    stage(configuration);\n    this.region = lesson.getRegion('experiment');\n    this.ViewClass = ViewClass;\n    this.viewOptions = viewOptions;\n    this.showApp();\n  },\n  showApp() {\n    this.view = new this.ViewClass(this.viewOptions);\n    demoInspector.observeRegion('root', this.region);\n    demoInspector.observeView('shell', this.view);\n    this.observe(this.view);\n    this.region.show(this.view);\n    this.ready?.(this.view);\n  },\n  reset() {\n    this.region.empty();\n    this.stopListening();\n    demoInspector.reset();\n    this.showApp();\n  },\n  onBeforeDestroy() {\n    this.region.empty();\n  },\n});\nexport { LessonController, demoInspector, story, explain, inspectRecipe };\n",
    "app.js": "import { View } from 'marionette';\nimport { Radio } from './radio-view.js';\n\n// The station replaces its radio through a Region, then challenges cleanup.\n// radio-view.js owns the widget; motion.js implements the integration.\nconst RadioStation = View.extend({\n  template: () => `\n    <div class=\"slot\"></div>\n    <div class=\"controls\"><button id=\"replace-widget\">1. Swap radio</button>\n    <button id=\"broadcast-radio\">2. Broadcast again 📡</button>\n    <button id=\"destroy-owner\">Close the station</button></div>\n  `,\n  regions: {\n    widget: '.slot',\n  },\n  ui: {\n    replace: '#replace-widget',\n    broadcast: '#broadcast-radio',\n    close: '#destroy-owner',\n  },\n  triggers: {\n    'click @ui.replace': 'click:replaceRadio',\n    'click @ui.broadcast': 'click:broadcast',\n    'click @ui.close': 'click:closeStation',\n  },\n  onRender() {\n    this.current = new Radio();\n    this.showChildView('widget', this.current);\n  },\n  onClickReplaceRadio() {\n    const old = this.current;\n    this.current = new Radio();\n    this.showChildView('widget', this.current);\n    this.triggerMethod('replace:radio', old, this.current);\n  },\n  onClickBroadcast() {\n    document.dispatchEvent(new Event('broadcast:radio'));\n    this.triggerMethod('send:broadcast');\n  },\n  onClickCloseStation() {\n    this.destroy();\n  },\n});\n\nexport { RadioStation };\n",
    "lesson.js": "import { LessonController, demoInspector, lesson, explain, story } from './lesson-ui.js';\nimport { RetiredRadio } from './radio-view.js';\n\nexport const RadioLesson = LessonController.extend({\n  observe(view) {\n    this.listenTo(view, 'render', () => demoInspector.observeView('first-widget', view.current));\n    this.listenTo(view, 'replace:radio', this.onReplaceRadio);\n    this.listenTo(view, 'send:broadcast', this.onSendBroadcast);\n    this.listenTo(view, 'before:destroy', () => this.snapshot(view.current));\n    this.listenTo(this.region, 'empty', () => {\n      demoInspector.check(\n        'parent-cleanup',\n        view.isDestroyed() &&\n          view.current.isDestroyed() &&\n          view.current.widget.getState().disposals === 1 &&\n          !this.region.hasView(),\n      );\n      explain(\n        'Station closed. Its final child was released.',\n        { file: 'app.js', symbol: 'RadioStation.onClickCloseStation' },\n        'Destroying the owner destroys its Regions and child Views. Their cleanup hooks release external work. Reset the demo to reopen it.',\n      );\n      story('Silence. Finally, a station that knows when to stop.');\n    });\n  },\n  ready() {\n    this.lastDeliveries = this.view.current.widget.getState().deliveries;\n    explain(\n      'A View owns an external widget.',\n      { file: 'radio-view.js', symbol: 'Radio.onAttach' },\n      'Attach starts the widget; detach releases it. Reattaching creates a fresh widget with the tuner’s saved settings. Swap the radio, then broadcast again to challenge cleanup.',\n    );\n  },\n  snapshot(view) {\n    lesson.showChildView('retired', new RetiredRadio({ model: view.snapshot() }));\n  },\n  onReplaceRadio(old, current) {\n    this.lastDeliveries = current.widget.getState().deliveries;\n    this.retired = old;\n    this.retiredDeliveries = old.widget.getState().deliveries;\n    demoInspector.observeView('replacement-widget', current);\n    this.snapshot(old);\n    demoInspector.check('old-view-destroyed', old.isDestroyed());\n    demoInspector.check(\n      'widget-disposed-once',\n      old.widget.getState().disposals === 1 && !old.widget.getState().playing,\n    );\n    explain(\n      'The Region replaced its child. Our hook unplugged it.',\n      [\n        { file: 'app.js', symbol: 'RadioStation.onClickReplaceRadio' },\n        { file: 'radio-view.js', symbol: 'Radio.releaseWidget' },\n      ],\n      'The frozen radio is a portrait. Broadcast again to check the actual retired widget—freezing a picture alone proves nothing.',\n      [\n        'The Region replaced its child.',\n        'Marionette invoked View cleanup.',\n        'Our code destroyed the widget.',\n      ],\n    );\n    story('A still picture is not proof of cleanup. Can the old receiver still hear us?');\n  },\n  onSendBroadcast() {\n    const current = this.view.current;\n    const live = current.widget.getState().deliveries;\n    if (!this.retired) {\n      story('The live radio heard broadcast ' + live + '. Swap it, then broadcast again.');\n      return;\n    }\n    const retired = this.retired.widget.getState().deliveries;\n    this.snapshot(this.retired);\n    demoInspector.check('old-widget-unsubscribed', retired === this.retiredDeliveries);\n    demoInspector.check(\n      'replacement-live',\n      !current.isDestroyed() && live === this.lastDeliveries + 1,\n    );\n    this.lastDeliveries = live;\n    explain(\n      'A new broadcast cannot reach the retired receiver.',\n      { file: 'motion.js', symbol: 'RadioWidget.onBeforeDestroy' },\n      'Marionette calls our cleanup hook; the widget removes its external listener. An abandoned chart or editor needs the same handoff to stop receiving updates.',\n      [\n        'You sent another broadcast.',\n        'The current receiver heard it.',\n        'The retired object’s counter did not increase.',\n      ],\n    );\n    story(\n      'Broadcast sent. Live receiver: ' +\n        live +\n        '. Retired receiver: ' +\n        retired +\n        '. The old object was checked again; it heard nothing new.',\n    );\n    demoInspector.updateObjects('radio', [\n      ['Retired receiver', 'DESTROYED', retired + ' broadcasts'],\n      ['Live receiver', 'LISTENING', live + ' broadcasts'],\n    ]);\n  },\n});\n",
    "main.js": "import { RadioStation } from './app.js';\nimport { RadioLesson } from './lesson.js';\nexport { inspectRecipe } from './lesson-ui.js';\n\nconst controller = new RadioLesson({\n  ViewClass: RadioStation,\n  configuration: {\n    icon: '📻',\n    title: 'Radio Ghostbusters',\n    question: 'When a View leaves, who switches off its widget?',\n    introduction:\n      'Charts, maps, and editors can keep working after their elements leave the page. This radio has the same problem to solve: who stops its animation and subscription?',\n    instruction:\n      'First swap the radio, then broadcast again. The live receiver should count the message; the retired receiver must not.',\n    evidence: [\n      {\n        id: 'old-view-destroyed',\n        label: 'The retired radio View was destroyed.',\n      },\n      {\n        id: 'widget-disposed-once',\n        label: 'Its widget was unplugged exactly once.',\n      },\n      {\n        id: 'old-widget-unsubscribed',\n        label: 'The old radio received no test broadcast.',\n      },\n      {\n        id: 'replacement-live',\n        label: 'The new radio received the broadcast.',\n      },\n      {\n        id: 'parent-cleanup',\n        label: 'Closing the station destroyed its owner and final radio.',\n      },\n    ],\n  },\n});\n\nexport const region = controller.region;\n",
    "motion.js": "import { MnObject } from 'marionette';\n\n// MnObject owns the imperative animation integration. The View owns this\n// object and destroys it explicitly. View updates use templates and events.\nconst RadioWidget = MnObject.extend({\n  createState() {\n    return {\n      deliveries: 0,\n      disposals: 0,\n      frames: 0,\n      frequency: 4,\n      playing: true,\n      levels: Array(9).fill(1),\n    };\n  },\n  initialize({ bars, frequency, playing }) {\n    this.bars = bars;\n    Object.assign(this.getState(), { frequency, playing });\n    this.receive = () => {\n      this.getState().deliveries++;\n      this.triggerMethod('receive:broadcast');\n    };\n    document.addEventListener('broadcast:radio', this.receive);\n  },\n  start() {\n    if (!this.getState().playing) {\n      return;\n    }\n    const paint = time => {\n      const state = this.getState();\n      if (!state.playing || this.isDestroyed()) {\n        return;\n      }\n      state.frames++;\n      state.levels = state.levels.map(\n        (_, index) =>\n          0.15 + Math.abs(Math.sin(time / (600 / state.frequency) + index * 0.7)) * 0.85,\n      );\n      // The only direct rendering is the external animation boundary.\n      this.bars.forEach((bar, index) => {\n        bar.style.transform = 'scaleY(' + state.levels[index] + ')';\n      });\n      if (state.frames % 6 === 0) {\n        this.triggerMethod('render:frame');\n      }\n      this.frame = requestAnimationFrame(paint);\n    };\n    this.frame = requestAnimationFrame(paint);\n  },\n  tune(frequency) {\n    this.getState().frequency = frequency;\n  },\n  toggle() {\n    const state = this.getState();\n    state.playing = !state.playing;\n    if (state.playing) {\n      this.start();\n    } else {\n      cancelAnimationFrame(this.frame);\n    }\n  },\n  onBeforeDestroy() {\n    this.getState().disposals++;\n    this.getState().playing = false;\n    cancelAnimationFrame(this.frame);\n    document.removeEventListener('broadcast:radio', this.receive);\n  },\n});\n\nexport { RadioWidget };\n",
    "radio-view.js": "import { View } from 'marionette';\nimport { Model, StateApi } from '@mnjs/data';\nimport { RadioWidget } from './motion.js';\n\n// Start with Radio: its Regions own the controls and readout.\n// RadioWidget in motion.js owns animation and the external subscription.\nconst RadioReadout = View.extend({\n  template: ({ frames, deliveries }) =>\n    `<small class=\"radio-frames\">${frames} animation frames</small><p class=\"widget\">📡 Broadcasts heard: ${deliveries}</p>`,\n});\nconst RadioTuner = View.extend({\n  createState() {\n    return new Model({\n      playing: true,\n      frequency: 4,\n    });\n  },\n  stateEvents: {\n    'change:playing': 'render',\n  },\n  templateContext() {\n    return this.getState().toObject();\n  },\n  template: ({\n    playing,\n    frequency,\n  }) => `<label class=\"tuning\">Tune the wiggles <input type=\"range\" min=\"1\" max=\"9\" value=\"${frequency}\" aria-label=\"Radio frequency\"></label>\n    <button class=\"pause-radio\">${playing ? 'Pause' : 'Resume'} the radio</button>`,\n  ui: {\n    frequency: '[type=range]',\n    pause: '.pause-radio',\n  },\n  events: {\n    'input @ui.frequency': 'onInputFrequency',\n  },\n  triggers: {\n    'click @ui.pause': 'click:playback',\n  },\n  onInputFrequency({ delegateTarget }) {\n    const frequency = Number(delegateTarget.value);\n    this.getState().set('frequency', frequency);\n    this.triggerMethod('change:frequency', frequency);\n  },\n  onClickPlayback() {\n    const state = this.getState();\n    state.set('playing', !state.get('playing'));\n    this.triggerMethod('change:playback');\n  },\n});\nRadioTuner.setStateApi(StateApi);\nconst Radio = View.extend({\n  template:\n    () => `<div class=\"radio-display\"><div class=\"radio-dial\">📻 &nbsp; FM 404 · SIGNAL FOUND</div>\n    <div class=\"equalizer\" aria-label=\"Live radio waveform\">${'<i></i>'.repeat(9)}</div><div class=\"readout\"></div></div><div class=\"tuner\"></div>`,\n  ui: {\n    bars: '.equalizer i',\n  },\n  regions: {\n    readout: '.readout',\n    tuner: '.tuner',\n  },\n  childViewEvents: {\n    'change:frequency': 'onChangeFrequency',\n    'change:playback': 'onChangePlayback',\n  },\n  onRender() {\n    this.showChildView(\n      'readout',\n      new RadioReadout({\n        model: {\n          frames: 0,\n          deliveries: 0,\n        },\n      }),\n    );\n    this.showChildView('tuner', new RadioTuner());\n  },\n  onAttach() {\n    // The tuner belongs to the View and survives detach/reattach.\n    // The external widget runs only while the View is attached.\n    const settings = this.getChildView('tuner').getState().toObject();\n    this.widget = new RadioWidget({\n      bars: this.getUI('bars'),\n      ...settings,\n    });\n    this.listenTo(this.widget, 'render:frame', this.onRenderFrame);\n    this.listenTo(this.widget, 'receive:broadcast', this.onReceiveBroadcast);\n    this.widget.start();\n    this.renderReadout();\n  },\n  onRenderFrame() {\n    this.renderReadout();\n  },\n  onReceiveBroadcast() {\n    this.renderReadout();\n  },\n  renderReadout() {\n    const readout = this.getChildView('readout');\n    readout.model = this.widget.getState();\n    readout.render();\n  },\n  onChangeFrequency(frequency) {\n    this.widget.tune(frequency);\n  },\n  onChangePlayback() {\n    this.widget.toggle();\n  },\n  snapshot() {\n    return {\n      ...this.widget.getState(),\n      levels: [...this.widget.getState().levels],\n    };\n  },\n  releaseWidget() {\n    this.stopListening(this.widget);\n    this.widget?.destroy();\n  },\n  onBeforeDetach() {\n    this.releaseWidget();\n  },\n  onBeforeDestroy() {\n    this.releaseWidget();\n  },\n});\nconst RetiredRadio = View.extend({\n  className: 'retired-radio',\n  template: ({\n    levels,\n    frames,\n    deliveries,\n  }) => `<p>RETIRED RADIO — its last frame, frozen. No ghost wiggles.</p>\n    <div class=\"radio-display\"><div class=\"radio-dial\">📻 &nbsp; FM 404 · SIGNAL FOUND</div>\n    <div class=\"equalizer\">${levels.map(level => `<i style=\"transform:scaleY(${level})\"></i>`).join('')}</div>\n    <small class=\"radio-frames\">${frames} animation frames</small><p class=\"widget\">📡 Broadcasts heard: ${deliveries}</p></div>`,\n});\n\nexport { Radio, RetiredRadio };\n"
  },
  "mission-control": {
    "html.js": "const escapeHTML = value =>\n  String(value ?? '').replace(\n    /[&<>\"']/g,\n    character =>\n      ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;',\n      })[character],\n  );\n\nexport { escapeHTML };\n",
    "lesson-ui.js": "import { View, Region, CollectionView, MnObject } from 'marionette';\nimport { escapeHTML } from './html.js';\nimport { sections } from './source.js';\n\nconst Story = View.extend({\n  tagName: 'p',\n  className: 'story',\n  attributes: {\n    role: 'status',\n  },\n  template: ({ text }) => escapeHTML(text),\n});\nconst Explanation = View.extend({\n  tagName: 'section',\n  className: 'lesson-step',\n  template: ({ title, excerpts, observation, steps }) => `\n    <small>FOLLOW THE CONNECTION</small><h2>${escapeHTML(title)}</h2>\n    <ol class=\"cause-chain\">${steps.map(step => `<li>${escapeHTML(step)}</li>`).join('')}</ol>\n    ${excerpts\n      .map(excerpt =>\n        excerpt\n          ? `\n      <section class=\"source-excerpt\" data-source-file=\"${escapeHTML(excerpt.file)}\" data-source-symbol=\"${escapeHTML(excerpt.symbol)}\">\n        <button class=\"source-link\" data-file=\"${escapeHTML(excerpt.file)}\" data-symbol=\"${escapeHTML(excerpt.symbol)}\">${escapeHTML(excerpt.file)} · ${escapeHTML(excerpt.symbol)} ↗</button>\n        <small class=\"source-caption\">RUNNING SOURCE · LINES ${excerpt.line}–${excerpt.endLine}</small>\n        <div class=\"source-lines\"><pre><code>${excerpt.highlighted}</code></pre></div>\n      </section>`\n          : '<p class=\"source-missing\">This method was removed or renamed in the running source. Use the source files below to inspect your edit.</p>',\n      )\n      .join('')}\n    <p>${escapeHTML(observation)}</p>`,\n  ui: {\n    source: '.source-link',\n  },\n  events: {\n    'click @ui.source': 'onClickSource',\n  },\n  onClickSource({ delegateTarget }) {\n    sourceSelection = {\n      file: delegateTarget.dataset.file,\n      symbol: delegateTarget.dataset.symbol,\n      requestId: ++sourceRequest,\n    };\n  },\n});\nconst ObjectBoard = View.extend({\n  className: 'object-board',\n  template: ({ objects }) =>\n    objects\n      .map(\n        ([name, status, detail]) => `<section>\n    <h3>${escapeHTML(name)}</h3><strong>${escapeHTML(status)}</strong><p>${escapeHTML(detail)}</p></section>`,\n      )\n      .join(''),\n});\nconst Receipt = View.extend({\n  tagName: 'li',\n  createState() {\n    return {\n      observed: null,\n    };\n  },\n  templateContext() {\n    return this.getState();\n  },\n  template: ({ label, observed }) =>\n    `${observed === null ? '○' : observed ? '✓' : '✗'} ${escapeHTML(label)}`,\n  onRender() {\n    const observed = this.getState().observed;\n\n    if (observed === null) {\n      delete this.el.dataset.result;\n    } else {\n      this.el.dataset.result = observed ? 'pass' : 'fail';\n    }\n  },\n});\nconst Receipts = CollectionView.extend({\n  tagName: 'ol',\n});\nconst Lesson = View.extend({\n  className: 'lesson',\n  template: ({ icon, title, introduction, question }) => `<header class=\"hero\">\n    <span class=\"mascot\" aria-hidden=\"true\">${escapeHTML(icon)}</span>\n    <div><div class=\"kicker\">A SMALL EXPERIMENT</div><h1>${escapeHTML(title)}</h1></div></header>\n    ${question ? `<h2 class=\"lesson-question\">${escapeHTML(question)}</h2>` : ''}\n    <p class=\"lede\">${escapeHTML(introduction)}</p>\n    <div class=\"lesson-layout\">\n      <div class=\"lesson-play\"><div id=\"experiment\"></div><div class=\"retired-slot\"></div></div>\n      <aside class=\"lesson-explanation\" aria-label=\"Code and consequence\"><div class=\"explanation-slot\"></div><div class=\"story-slot\"></div></aside>\n    </div>\n    <details class=\"proof\" aria-label=\"Observed evidence\">\n      <summary>Inspector · objects &amp; checks</summary>\n      <p class=\"fine\">Peek under the floorboards. ○ means not tried yet; ✓ means an actual object passed the check.</p>\n      <div class=\"inspector-retired-slot\"></div><div class=\"board-slot\"></div><div class=\"receipts-slot\"></div>\n    </details>`,\n  regions: {\n    experiment: '#experiment',\n    story: '.story-slot',\n    retired: '.retired-slot',\n    retiredEvidence: '.inspector-retired-slot',\n    explanation: '.explanation-slot',\n    board: '.board-slot',\n    receipts: '.receipts-slot',\n  },\n  onRender() {\n    this.showChildView('receipts', new Receipts());\n    for (const { id, label } of this.model.evidence) {\n      const receipt = new Receipt({\n        model: {\n          label,\n        },\n      });\n\n      receiptViews.set(id, receipt);\n      this.getChildView('receipts').addChildView(receipt);\n    }\n  },\n});\nconst lifecycle = [];\nconst checks = new Map();\nconst views = [];\nconst receiptViews = new Map();\nlet lifecycleDropped = 0;\nexport let lesson;\nlet sourceSelection,\n  sourceRequest = 0;\n\n// Demo instrumentation only: these methods observe ownership; they do not create it.\nconst observedRegions = new Map();\nconst objectGroups = new Map();\nconst demoInspector = {\n  observeView(name, view) {\n    views.push({\n      name,\n      view,\n    });\n    for (const event of ['render', 'attach', 'detach', 'before:destroy', 'destroy']) {\n      view.on(event, () => {\n        lifecycle.push(name + ':' + event);\n        if (lifecycle.length > 40) {\n          lifecycle.shift();\n          lifecycleDropped++;\n        }\n      });\n    }\n\n    return view;\n  },\n  check(id, observed) {\n    checks.set(id, {\n      id,\n      expected: true,\n      observed: Boolean(observed),\n    });\n    const receipt = receiptViews.get(id);\n\n    if (receipt) {\n      receipt.getState().observed = Boolean(observed);\n      receipt.render();\n    }\n  },\n  observeRegion(name, region) {\n    observedRegions.set(name, region);\n  },\n  showRetired(view) {\n    lesson.showChildView('retiredEvidence', view);\n  },\n  updateObjects(name, objects) {\n    objectGroups.set(name, objects);\n    lesson.showChildView(\n      'board',\n      new ObjectBoard({\n        model: {\n          objects: [...objectGroups.values()].flat(),\n        },\n      }),\n    );\n  },\n  reset() {\n    lesson.getRegion('retiredEvidence').empty();\n    objectGroups.clear();\n    lesson.getRegion('board').empty();\n    checks.clear();\n    views.length = lifecycle.length = 0;\n    lifecycleDropped = 0;\n    observedRegions.clear();\n    this.observeRegion('root', lesson.getRegion('experiment'));\n    for (const receipt of receiptViews.values()) {\n      receipt.getState().observed = null;\n      receipt.render();\n    }\n  },\n  inspect() {\n    return {\n      sourceSelection,\n      checks: [...checks.values()],\n      lifecycle,\n      lifecycleDropped,\n      views,\n      regions: [...observedRegions].map(([name, region]) => ({\n        name,\n        region,\n      })),\n    };\n  },\n};\n\nfunction story(text) {\n  lesson.showChildView(\n    'story',\n    new Story({\n      model: {\n        text,\n      },\n    }),\n  );\n}\nfunction explain(title, references, observation, steps = []) {\n  const excerpts = [references].flat().map(({ file, symbol }) => sections[file]?.[symbol] || null);\n  lesson.showChildView(\n    'explanation',\n    new Explanation({\n      model: {\n        title,\n        excerpts,\n        observation,\n        steps,\n      },\n    }),\n  );\n}\nfunction stage({ icon, title, question, introduction, instruction, evidence }) {\n  lesson = new Lesson({\n    model: {\n      icon,\n      title,\n      introduction,\n      question,\n      evidence,\n    },\n  });\n  new Region({\n    el: '#app',\n  }).show(lesson);\n  if (instruction) story(instruction);\n}\nfunction inspectRecipe() {\n  return demoInspector.inspect();\n}\n// The controller owns subscriptions and teaching UI. App Views never import it.\nconst LessonController = MnObject.extend({\n  initialize({ configuration, ViewClass, viewOptions = {} }) {\n    stage(configuration);\n    this.region = lesson.getRegion('experiment');\n    this.ViewClass = ViewClass;\n    this.viewOptions = viewOptions;\n    this.showApp();\n  },\n  showApp() {\n    this.view = new this.ViewClass(this.viewOptions);\n    demoInspector.observeRegion('root', this.region);\n    demoInspector.observeView('shell', this.view);\n    this.observe(this.view);\n    this.region.show(this.view);\n    this.ready?.(this.view);\n  },\n  reset() {\n    this.region.empty();\n    this.stopListening();\n    demoInspector.reset();\n    this.showApp();\n  },\n  onBeforeDestroy() {\n    this.region.empty();\n  },\n});\nexport { LessonController, demoInspector, story, explain, inspectRecipe };\n",
    "app.js": "import { View } from 'marionette';\nimport { MissionControl, StationLoader, StationControls, MissionChapters } from './readiness.js';\n\n// Two lessons, one Application. This shell coordinates chapter navigation.\n// readiness.js gates the root View; flight.js owns each cancellable delivery.\nconst StationConsole = View.extend({\n  className: 'mission-console',\n  template: () => `\n    <div class=\"chapters-slot\"></div>\n    <div class=\"controls-slot station-controls\"></div>\n    <div class=\"station-stage\">\n      <div class=\"station-screen\"></div>\n      <div class=\"loader-slot\"></div>\n    </div>\n    `,\n  ui: {\n    screen: '.station-screen',\n  },\n  regions: {\n    chapters: '.chapters-slot',\n    loader: '.loader-slot',\n    controls: '.controls-slot',\n  },\n  childViewEvents: {\n    'select:readiness': 'onSelectReadiness',\n    'select:flight': 'onSelectFlight',\n    'click:open': 'onClickOpen',\n    'click:close': 'onClickClose',\n    'click:failPreparation': 'onClickFailPreparation',\n    'click:destroy': 'onClickDestroy',\n    'click:reset': 'onClickReset',\n    'toggle:exploration': 'onToggleExploration',\n  },\n  onSelectReadiness() {\n    this.showChapter(1);\n  },\n  onSelectFlight() {\n    this.showChapter(2);\n  },\n  showChapter(chapter) {\n    this.chapter = chapter;\n    this.el.dataset.chapter = chapter;\n    this.triggerMethod('change:chapter', chapter);\n    this.showChildView(\n      'chapters',\n      new MissionChapters({\n        model: {\n          chapter,\n          ready: this.phase === 'open',\n        },\n      }),\n    );\n  },\n  onToggleExploration(exploring) {\n    this.exploring = exploring;\n  },\n  onRender() {\n    this.application = new MissionControl({\n      region: {\n        el: this.getUI('screen')[0],\n      },\n    });\n    this.attempt = 0;\n    this.present('closed', 'CLOSED. No flight screen exists yet.');\n  },\n  async onClickOpen() {\n    if (this.phase === 'opening') {\n      this.preparationStep = this.getChildView('loader').advance();\n      this.showControls();\n      return;\n    }\n    const attempt = ++this.attempt;\n    this.present(\n      'opening',\n      'PREPARING. The flight screen is still absent. Each click opens another 25%.',\n    );\n    try {\n      const started = await this.application.start({\n        loader: this.getChildView('loader'),\n      });\n      this.triggerMethod('settle:start', started);\n      if (!started) {\n        return;\n      }\n      if (attempt !== this.attempt || this.isDestroyed()) {\n        return;\n      }\n      this.present(\n        'open',\n        'OPEN. Preparation completed; the Application attached its flight screen.',\n      );\n    } catch (error) {\n      if (attempt !== this.attempt || this.isDestroyed()) {\n        return;\n      }\n      this.triggerMethod('fail:start', error);\n      this.present(\n        'failed',\n        'FAILED. Antenna in cheese. No flight screen. Repair by opening again.',\n      );\n    }\n  },\n  async onClickClose() {\n    const attempt = ++this.attempt;\n    await this.application.stop();\n    if (attempt !== this.attempt || this.isDestroyed()) {\n      return;\n    }\n    this.present(\n      'closed',\n      'CLOSED. The Application has no flight screen. Open again for a fresh start.',\n    );\n  },\n  onClickFailPreparation() {\n    this.getChildView('loader').fail();\n  },\n  async onClickDestroy() {\n    const attempt = ++this.attempt;\n    await this.application.destroy();\n    if (attempt !== this.attempt || this.isDestroyed()) {\n      return;\n    }\n    this.present(\n      'destroyed',\n      'DESTROYED. Even mission control has left the building. Reset to build a new Application.',\n    );\n  },\n  onClickReset() {\n    this.triggerMethod('reset:station');\n  },\n  showControls() {\n    this.showChildView(\n      'controls',\n      new StationControls({\n        model: {\n          phase: this.phase,\n          exploring: this.exploring,\n          preparationStep: this.preparationStep,\n        },\n      }),\n    );\n  },\n  present(phase, message) {\n    this.phase = phase;\n    this.preparationStep = phase === 'opening' ? 1 : phase === 'open' ? 4 : 0;\n    this.showChildView(\n      'loader',\n      new StationLoader({\n        model: {\n          phase,\n          message,\n        },\n      }),\n    );\n    this.showControls();\n    this.showChapter(1);\n    this.triggerMethod('change:phase', phase);\n  },\n  onBeforeDestroy() {\n    this.application.destroy().catch(error => console.error(error));\n  },\n});\n\nexport { StationConsole };\n",
    "flight.js": "import { View } from 'marionette';\nimport { animateFlight } from './motion.js';\nimport { escapeHTML } from './html.js';\n\n// Region replacement destroys the old Mission. Its owned AbortController\n// cancels the flight; only successful completion updates the View's state.\nconst flightDuration = 3000;\nconst beamWindow = {\n  start: 0.4,\n  end: 0.6,\n};\nfunction flightContext({ progress, status, commits }) {\n  const outcomes = {\n    ready: ['🚀', 'Ready on the launchpad. Three seconds to the moon.'],\n    flying: ['🚀', 'In flight. The moon has ordered extra cheese.'],\n    landed: ['🧀', 'Delivered! One cheese write. Zero interplanetary invoices paid.'],\n    failed: ['💥', 'Engine failed. No cheese delivered. Try a fresh mission.'],\n    retired: ['🚀', `Retired: ${commits} deliveries. This flight cannot do more work.`],\n  };\n  const [icon, message] = outcomes[status];\n  return {\n    icon,\n    message,\n    left: 10 + 80 * progress,\n  };\n}\nconst flightTemplate = ({ left, icon, message }) => `\n  <div class=\"flight-path\">\n    <span class=\"planet earth\">🌍</span>\n    <div class=\"beam-zone\" aria-hidden=\"true\"></div>\n    <span class=\"beam-cannon\" aria-hidden=\"true\">📡</span>\n    <small class=\"beam-label\">BEAM ZONE · 40–60%</small>\n    <span class=\"rocket\" aria-label=\"Cheese delivery rocket\"\n      style=\"left:${left}%;transform:translateX(-50%) rotate(45deg)\">${icon}</span>\n    <span class=\"planet moon\">🌕</span>\n  </div>\n  <p class=\"result\" role=\"status\">${message}</p>`;\nconst Mission = View.extend({\n  ui: {\n    rocket: '.rocket',\n  },\n  createState() {\n    return {\n      controller: new AbortController(),\n      commits: 0,\n      status: 'flying',\n      progress: 0,\n    };\n  },\n  templateContext() {\n    return flightContext(this.getState());\n  },\n  template: flightTemplate,\n  // An explicit background task, started by FlightDeck after region.show.\n  // View lifecycle hooks remain synchronous; they do not await this Promise.\n  async fly({ guided = false } = {}) {\n    const state = this.getState();\n    const [rocket] = this.getUI('rocket');\n    this.animation = animateFlight(rocket, {\n      duration: flightDuration,\n      guided,\n      onPause: () => this.triggerMethod('pause:flight'),\n    });\n    const cancel = () => this.animation.cancel();\n    state.controller.signal.addEventListener('abort', cancel, {\n      once: true,\n    });\n    try {\n      await this.animation.finished;\n      if (state.controller.signal.aborted || this.isDestroyed()) {\n        return;\n      }\n      Object.assign(state, {\n        commits: state.commits + 1,\n        status: 'landed',\n        progress: 1,\n      });\n    } catch (error) {\n      if (state.controller.signal.aborted) {\n        return;\n      }\n      if (state.status !== 'failed') {\n        throw error;\n      }\n    } finally {\n      state.controller.signal.removeEventListener('abort', cancel);\n    }\n    this.animation.cancel();\n    this.render();\n    this.triggerMethod('settle:flight', this);\n  },\n  getProgress() {\n    return ['running', 'paused'].includes(this.animation?.playState)\n      ? this.animation.currentTime / flightDuration\n      : this.getState().progress;\n  },\n  snapshot() {\n    const state = this.getState();\n    const progress = this.getProgress();\n    return {\n      progress,\n      commits: state.commits,\n      status: 'retired',\n    };\n  },\n  fail() {\n    const state = this.getState();\n    if (state.status !== 'flying') {\n      return;\n    }\n    Object.assign(state, {\n      progress: this.snapshot().progress,\n      status: 'failed',\n    });\n    this.animation.cancel();\n  },\n  onBeforeDestroy() {\n    this.getState().controller.abort();\n  },\n});\nconst RetiredFlight = View.extend({\n  className: 'retired-flight',\n  templateContext() {\n    return flightContext(this.model);\n  },\n  template: model =>\n    '<small>RETIRED FLIGHT — frozen at the moment its View left</small>' + flightTemplate(model),\n});\n// The beam is a sibling View, so its flash survives a hit destroying the ship.\nconst Beam = View.extend({\n  className: 'beam',\n  template: () => '',\n  flash() {\n    this.animation = this.el.animate(\n      [\n        {\n          opacity: 1,\n        },\n        {\n          opacity: 0,\n        },\n      ],\n      {\n        duration: 500,\n        fill: 'forwards',\n      },\n    );\n  },\n  onBeforeDestroy() {\n    this.animation?.cancel();\n  },\n});\nconst BeamFeedback = View.extend({\n  className: 'beam-feedback',\n  attributes: {\n    role: 'status',\n  },\n  template: ({ message }) => escapeHTML(message),\n});\nconst FlightControls = View.extend({\n  className: 'controls',\n  createState() {\n    return {\n      exploring: false,\n    };\n  },\n  templateContext() {\n    return this.getState();\n  },\n  events: {\n    'click @ui.exploration': 'onClickExploration',\n  },\n  onClickExploration() {\n    this.getState().exploring = !this.getState().exploring;\n  },\n  template: ({\n    flying,\n    exploring,\n    paused,\n  }) => `<button id=\"guided-flight\">Guided flight · pause halfway</button>\n    <button id=\"cancel-flight\" ${paused ? '' : 'disabled'}>Cancel this flight</button>\n    <p class=\"fine flight-game-label\">Or play: launch a three-second courier and time your beam.</p>\n    <button id=\"launch-worker\">Launch / restart 🚀</button>\n    <button id=\"fire-beam\" ${flying ? '' : 'disabled'}>Fire beam ⚡</button>\n    <details class=\"flight-more\" ${exploring ? 'open' : ''}><summary>Try an engine failure</summary><button id=\"fail-worker\" ${flying ? '' : 'disabled'}>Break the engine 💥</button></details>`,\n  ui: {\n    guided: '#guided-flight',\n    cancel: '#cancel-flight',\n    launch: '#launch-worker',\n    beam: '#fire-beam',\n    fail: '#fail-worker',\n    exploration: '.flight-more > summary',\n  },\n  triggers: {\n    'click @ui.guided': 'click:guidedFlight',\n    'click @ui.cancel': 'click:cancelFlight',\n    'click @ui.launch': 'click:launch',\n    'click @ui.beam': 'click:fireBeam',\n    'click @ui.fail': 'click:breakEngine',\n  },\n});\nconst FlightDeck = View.extend({\n  className: 'flight-deck',\n  template: () => `\n    <div class=\"flight-arena\">\n      <div class=\"slot flight-slot\">${flightTemplate(\n        flightContext({\n          progress: 0,\n          status: 'ready',\n          commits: 0,\n        }),\n      )}</div>\n      <div class=\"beam-slot\"></div>\n    </div>\n    <div class=\"controls-slot\"></div><div class=\"feedback-slot\"></div>\n\n  `,\n  regions: {\n    worker: '.slot',\n    beam: '.beam-slot',\n    feedback: '.feedback-slot',\n    controls: '.controls-slot',\n  },\n  childViewEvents: {\n    'click:guidedFlight': 'onClickGuidedFlight',\n    'click:cancelFlight': 'onClickCancelFlight',\n    'click:launch': 'onClickLaunch',\n    'click:fireBeam': 'onClickFireBeam',\n    'click:breakEngine': 'onClickBreakEngine',\n  },\n  childViewTriggers: {\n    'pause:flight': 'pause:flight',\n    'settle:flight': 'settle:flight',\n  },\n  onRender() {\n    this.showChildView(\n      'controls',\n      new FlightControls({\n        model: { flying: false, paused: false },\n      }),\n    );\n  },\n  retire() {\n    const old = this.getChildView('worker');\n    if (!old) {\n      return;\n    }\n    this.triggerMethod('retire:flight', old);\n  },\n  onClickGuidedFlight() {\n    this.launch({ guided: true });\n  },\n  onClickLaunch() {\n    this.launch({ guided: false });\n  },\n  launch({ guided }) {\n    this.retire();\n    this.getRegion('beam').empty();\n    this.feedback(\n      guided\n        ? 'The ship will pause at 50%. Its Promise will still be pending.'\n        : 'Aim for the marked lane: 40–60% of the flight.',\n    );\n    this.current = new Mission();\n    this.showChildView('worker', this.current);\n    this.triggerMethod('launch:flight', this.current);\n    this.current\n      .fly({\n        guided,\n      })\n      .catch(error => this.triggerMethod('fail:flight', error));\n    this.updateControls({ flying: true });\n  },\n  onPauseFlight() {\n    this.updateControls({ flying: true, paused: true });\n    this.feedback(\n      'Paused at 50%. The View is alive, the Promise is pending, and deliveries are still zero. Click Cancel this flight when you are ready.',\n    );\n  },\n  onClickCancelFlight() {\n    this.cancelFlight();\n  },\n  onClickFireBeam() {\n    const mission = this.getChildView('worker');\n    const progress = mission.getProgress();\n    const beam = new Beam();\n    this.showChildView('beam', beam);\n    beam.flash();\n    if (progress >= beamWindow.start && progress <= beamWindow.end) {\n      this.triggerMethod('hit:flight', progress);\n    } else {\n      this.triggerMethod('miss:flight', progress);\n    }\n  },\n  onMissFlight(progress) {\n    this.feedback(\n      `Miss at ${Math.round(progress * 100)}%. The ship keeps flying. Fire between 40% and 60%.`,\n    );\n  },\n  feedback(message) {\n    this.showChildView(\n      'feedback',\n      new BeamFeedback({\n        model: {\n          message,\n        },\n      }),\n    );\n  },\n  onHitFlight(progress) {\n    this.cancelFlight();\n    this.feedback(\n      `Hit at ${Math.round(progress * 100)}%! View destroyed. Flight aborted. Zero cheese delivered.`,\n    );\n  },\n  cancelFlight() {\n    this.retire();\n    this.getRegion('worker').empty();\n    this.updateControls({ flying: false });\n    this.triggerMethod('cancel:flight');\n    this.feedback(\n      'View destroyed. Flight aborted. Zero cheese delivered. The station is still running.',\n    );\n  },\n  onClickBreakEngine() {\n    this.current.fail();\n  },\n  updateControls({ flying, paused = false }) {\n    const controls = this.getChildView('controls');\n    Object.assign(controls.model, { flying, paused });\n    controls.render();\n  },\n  onSettleFlight() {\n    this.updateControls({ flying: false });\n  },\n});\n\nexport { Mission, FlightDeck, RetiredFlight };\n",
    "lesson.js": "import { LessonController, demoInspector, explain, story } from './lesson-ui.js';\nimport { RetiredFlight } from './flight.js';\n\nconst readiness = symbol => ({ file: 'readiness.js', symbol });\nconst flight = symbol => ({ file: 'flight.js', symbol });\nconst shell = symbol => ({ file: 'app.js', symbol });\n\nexport const MissionLesson = LessonController.extend({\n  observe(view) {\n    this.phase = this.retired = this.current = this.root = this.applicationRegion = null;\n    this.listenTo(view, 'change:phase', this.onChangePhase);\n    this.listenTo(view, 'change:chapter', this.onChangeChapter);\n    this.listenTo(view, 'settle:start', this.onSettleStart);\n    this.listenTo(view, 'fail:start', this.onFailStart);\n    this.listenTo(view, 'reset:station', this.reset);\n  },\n  onSettleStart(started) {\n    if (started === false) {\n      demoInspector.check('cancelled-start-false', true);\n    }\n  },\n  onFailStart(error) {\n    demoInspector.check(\n      'current-failure-rejects',\n      error.message === 'The antenna fell into the cheese' && !this.view.application.isRunning(),\n    );\n  },\n  ready() {\n    this.onChangeChapter(1);\n  },\n  onChangeChapter(chapter) {\n    if (chapter === 1) {\n      explain(\n        'Lesson 1 · Readiness gates the app screen.',\n        readiness('MissionControl.onBeforeStart'),\n        'Open the hangar in four deliberate steps. The pending Promise prevents the app from showing its root View. Cancel or fail an opening to compare those outcomes.',\n      );\n    } else {\n      explain(\n        'Lesson 2 · A View owns unfinished work.',\n        flight('Mission.onBeforeDestroy'),\n        'Start the guided flight. It pauses halfway so you can read before cancelling. The beam game uses this same cleanup hook.',\n        ['Launch a ship View.', 'Read the pending state.', 'Remove the View and follow cleanup.'],\n      );\n      story('The ship gets a job—and a very clear cancellation policy.');\n    }\n  },\n  onChangePhase(phase) {\n    const view = this.view;\n    const app = view.application;\n    const region = (this.applicationRegion ||= app.getRegion());\n    const previous = this.phase;\n    this.phase = phase;\n    demoInspector.observeRegion('application.root', region);\n    if (phase === 'opening') {\n      this.writes = app.getState().readinessWrites;\n      explain(\n        'Readiness is pending. No root View exists.',\n        readiness('MissionControl.onBeforeStart'),\n        'Each click opens another 25%. Between clicks, start() stays pending. The fourth click completes preparation.',\n      );\n    }\n    if (phase === 'open') {\n      this.root = app.getView();\n      demoInspector.observeView('flight-screen', this.root);\n      demoInspector.observeRegion('mission.slot', this.root.getRegion('worker'));\n      this.listenTo(this.root, 'retire:flight', this.onRetireFlight);\n      this.listenTo(this.root, 'launch:flight', this.onLaunchFlight);\n      this.listenTo(this.root, 'pause:flight', this.onPauseFlight);\n      this.listenTo(this.root, 'settle:flight', this.onSettleFlight);\n      this.listenTo(this.root, 'cancel:flight', this.onCancelFlight);\n      this.listenTo(this.root, 'hit:flight', this.onHitFlight);\n      this.listenTo(this.root, 'miss:flight', this.onMissFlight);\n      demoInspector.check('fresh-start-true', app.isRunning());\n      demoInspector.check('root-shown', this.root.isAttached());\n      explain(\n        'Readiness succeeded. The root View is attached.',\n        readiness('MissionControl.onStart'),\n        'Preparation resolved before Application invoked onStart. Choose Lesson 2 above to work with the ship.',\n        ['Preparation finished.', 'Application invoked onStart.', 'The root View was attached.'],\n      );\n      story('Hangar open: 100%. No need to hurry. The next lesson waits for you.');\n    }\n    if (phase === 'failed') {\n      explain(\n        'Failure rejects start. It creates no app screen.',\n        shell('StationConsole.onClickOpen'),\n        'An error is different from cancellation, which returns false. Open again to retry the same Application.',\n      );\n    }\n    if (phase === 'closed' || phase === 'destroyed') {\n      if (previous === 'opening') {\n        demoInspector.check('readiness-aborted', app.getState().signal.aborted);\n        demoInspector.check('no-stale-write', app.getState().readinessWrites === this.writes);\n      }\n      if (this.root) {\n        demoInspector.check('stopped-root-destroyed', this.root.isDestroyed() && !region.hasView());\n      }\n      if (this.current?.getState().status === 'flying') {\n        demoInspector.check(\n          'close-cancels-flight',\n          this.current.isDestroyed() &&\n            this.current.getState().controller.signal.aborted &&\n            this.current.getState().commits === 0,\n        );\n      }\n      if (previous) {\n        explain(\n          'Closing the app ends its children’s work.',\n          shell('StationConsole.onClickClose'),\n          'Stopping Application destroys its root View, which destroys its child Regions and ship. Cancelling one ship leaves the app running.',\n        );\n      }\n      if (phase === 'destroyed') {\n        demoInspector.check('application-destroyed', app.isDestroyed() && !region.hasView());\n        explain(\n          'The Application’s lifetime has ended.',\n          shell('StationConsole.onClickDestroy'),\n          'Stop permits another opening. Destroy ends the instance; Reset creates another.',\n        );\n      }\n    }\n    demoInspector.updateObjects('application', [\n      [\n        'Application',\n        phase.toUpperCase(),\n        app.getState().readinessWrites + ' readiness completions',\n      ],\n      [\n        'Root View',\n        region.hasView() ? 'ATTACHED' : 'ABSENT',\n        app.getState().starts + ' successful starts',\n      ],\n    ]);\n  },\n  onRetireFlight(old) {\n    this.retired = old;\n    demoInspector.showRetired(new RetiredFlight({ model: old.snapshot() }));\n  },\n  verifyRetirement() {\n    if (!this.retired) {\n      return;\n    }\n    const state = this.retired.getState();\n    demoInspector.check('old-work-aborted', state.controller.signal.aborted);\n    demoInspector.check('old-view-destroyed', this.retired.isDestroyed());\n    if (state.status === 'flying') {\n      demoInspector.check('no-stale-commit', state.commits === 0);\n    }\n  },\n  onLaunchFlight(mission) {\n    this.verifyRetirement();\n    this.current = mission;\n    demoInspector.observeView('mission-' + mission.cid, mission);\n    explain(\n      'A new View owns one unfinished delivery.',\n      flight('Mission.fly.completion'),\n      'This excerpt shows the actual await, cancellation guard, and delivery write in Mission.fly. The guided flight pauses halfway; the game keeps moving.',\n    );\n    story(\n      'The cheese is in transit. It does not count as delivered just because we feel optimistic.',\n    );\n  },\n  onPauseFlight() {\n    explain(\n      'Paused is not finished. Nothing has been delivered.',\n      flight('Mission.fly.completion'),\n      'The animation is paused at the await. The following guard and delivery write have not run. Cancel this flight when you have finished reading.',\n      [\n        'The ship reached its reading stop.',\n        'The View and Promise remain alive.',\n        'Choose Cancel this flight.',\n      ],\n    );\n  },\n  onHitFlight() {\n    demoInspector.check(\n      'beam-hit-aborts',\n      this.retired.isDestroyed() && this.retired.getState().controller.signal.aborted,\n    );\n  },\n  onMissFlight() {\n    demoInspector.check(\n      'beam-miss-continues',\n      !this.current.isDestroyed() && !this.current.getState().controller.signal.aborted,\n    );\n    explain(\n      'A miss leaves the same View alive.',\n      flight('FlightDeck.onClickFireBeam'),\n      'No Region was emptied. The same ship and unfinished job continue.',\n    );\n  },\n  onCancelFlight() {\n    this.verifyRetirement();\n    demoInspector.check(\n      'station-survives-cancel',\n      this.view.application.isRunning() && !this.root.isDestroyed(),\n    );\n    explain(\n      'The View left. Our hook aborted its work.',\n      [flight('FlightDeck.cancelFlight'), flight('Mission.onBeforeDestroy')],\n      'Marionette invokes the View lifecycle. Our AbortController cancels the animation so it cannot record a delivery.',\n      [\n        'You cancelled the ship’s delivery.',\n        'The Region removed its View.',\n        'Marionette called onBeforeDestroy.',\n        'Our hook aborted the flight.',\n        'No cheese was delivered.',\n      ],\n    );\n    story(\n      'Zero cheese delivered. The station remains open for the next questionable space errand.',\n    );\n  },\n  onSettleFlight(mission) {\n    const state = mission.getState();\n    if (state.status === 'landed') {\n      demoInspector.check('replacement-completed', state.commits === 1);\n    }\n    this.verifyRetirement();\n    explain(\n      state.status === 'landed'\n        ? 'The finished flight records one delivery.'\n        : 'The failed flight records no delivery.',\n      flight('Mission.fly.completion'),\n      'Read the await, the cancellation guard, and the successful write in the actual method. A failed or cancelled operation cannot take the success path.',\n    );\n  },\n});\n",
    "main.js": "import { StationConsole } from './app.js';\nimport { MissionLesson } from './lesson.js';\nexport { inspectRecipe } from './lesson-ui.js';\n\nconst controller = new MissionLesson({\n  ViewClass: StationConsole,\n  configuration: {\n    icon: '🚀',\n    title: 'Cheese Patrol',\n    introduction: 'Prepare the app. Then launch a ship whose View owns the delivery.',\n    evidence: [\n      {\n        id: 'beam-miss-continues',\n        label: 'A missed beam left the flight alive.',\n      },\n      {\n        id: 'beam-hit-aborts',\n        label: 'A beam hit destroyed the ship View and aborted its flight.',\n      },\n      {\n        id: 'cancelled-start-false',\n        label: 'Cancelling preparation returned false from Application.start().',\n      },\n      {\n        id: 'readiness-aborted',\n        label: 'The pending readiness signal was aborted.',\n      },\n      {\n        id: 'no-stale-write',\n        label: 'Cancelled readiness made no successful write.',\n      },\n      {\n        id: 'fresh-start-true',\n        label: 'A complete preparation returned true.',\n      },\n      {\n        id: 'root-shown',\n        label: 'Readiness succeeded before the flight screen attached.',\n      },\n      {\n        id: 'current-failure-rejects',\n        label: 'Broken preparation rejected start as an error.',\n      },\n      {\n        id: 'old-work-aborted',\n        label: 'The retired rocket’s AbortController was aborted.',\n      },\n      {\n        id: 'old-view-destroyed',\n        label: 'The retired rocket View was destroyed.',\n      },\n      {\n        id: 'no-stale-commit',\n        label: 'A cancelled rocket made zero deliveries.',\n      },\n      {\n        id: 'replacement-completed',\n        label: 'A successful rocket delivered exactly once.',\n      },\n      {\n        id: 'station-survives-cancel',\n        label: 'Cancelling a rocket left the Application and flight screen alive.',\n      },\n      {\n        id: 'stopped-root-destroyed',\n        label: 'Closing the Application destroyed its flight screen.',\n      },\n      {\n        id: 'close-cancels-flight',\n        label: 'Closing during flight destroyed the rocket and cancelled delivery.',\n      },\n      {\n        id: 'application-destroyed',\n        label: 'Destroy ended the Application and emptied its Region.',\n      },\n    ],\n  },\n});\n\nexport const region = controller.region;\n",
    "motion.js": "// Browser animation mechanics. Mission owns the AbortController and decides\n// whether a finished animation may record a delivery; this file does neither.\nfunction animateFlight(rocket, { duration, guided, onPause }) {\n  const animation = rocket.animate(\n    [\n      {\n        left: '10%',\n      },\n      {\n        left: '90%',\n      },\n    ],\n    {\n      duration,\n      fill: 'forwards',\n      easing: 'linear',\n    },\n  );\n  let pauseTimer;\n  if (guided) {\n    pauseTimer = setTimeout(() => {\n      animation.pause();\n      animation.currentTime = duration / 2;\n      onPause();\n    }, duration / 2);\n  }\n  const clearPause = () => clearTimeout(pauseTimer);\n\n  // Completion, cancellation, and failure all release the teaching timer.\n  animation.finished.then(clearPause, clearPause);\n  return animation;\n}\nfunction animateHangar(doors) {\n  return [...doors].map((door, index) =>\n    door.animate(\n      [\n        {\n          transform: 'translateX(0)',\n        },\n        {\n          transform: 'translateX(' + (index === 0 ? -100 : 100) + '%)',\n        },\n      ],\n      {\n        duration: 1000,\n        fill: 'forwards',\n      },\n    ),\n  );\n}\n\nexport { animateFlight, animateHangar };\n",
    "readiness.js": "import { View, Application } from 'marionette';\nimport { FlightDeck } from './flight.js';\nimport { animateHangar } from './motion.js';\nimport { escapeHTML } from './html.js';\n\n// Application readiness is a different boundary: there is no flight screen\n// until preparation succeeds. Stop cancels this start; failure rejects it.\nconst PreparationStatus = View.extend({\n  tagName: 'p',\n  className: 'station-status',\n  attributes: {\n    role: 'status',\n  },\n  template: ({ message }) => escapeHTML(message),\n});\nconst StationLoader = View.extend({\n  regions: {\n    status: '.station-status-slot',\n  },\n  onRender() {\n    this.showStatus(this.model.message);\n  },\n  showStatus(message) {\n    this.showChildView(\n      'status',\n      new PreparationStatus({\n        model: {\n          message,\n        },\n      }),\n    );\n  },\n  advance() {\n    this.step = Math.min(this.step + 1, 4);\n    this.animations.forEach(animation => {\n      if (this.step === 4) {\n        animation.finish();\n      } else {\n        animation.currentTime = this.step * 250;\n      }\n    });\n    this.showStatus(\n      'OPENING. ' +\n        this.step * 25 +\n        '% · step ' +\n        this.step +\n        '/4. Readiness waits for all four steps.',\n    );\n    return this.step;\n  },\n  ui: {\n    doors: '.hangar-door',\n  },\n  template: ({ phase, message }) => `\n    <section class=\"station-loader\" data-phase=\"${phase}\">\n      <div class=\"hangar\" aria-label=\"Ship waiting for the hangar to open\">\n        <span class=\"hangar-ship\" aria-hidden=\"true\">🚀</span>\n        <div class=\"hangar-door\"></div><div class=\"hangar-door\"></div>\n        <span class=\"hangar-sign\">CHEESE COURIER · LAUNCH BAY</span>\n      </div>\n      <div class=\"station-status-slot\"></div>\n    </section>`,\n  prepare(signal) {\n    this.animations = animateHangar(this.getUI('doors'));\n    // This paused timeline is a progress ruler, not a countdown.\n    this.step = 0;\n    this.animations.forEach(animation => {\n      animation.pause();\n      animation.currentTime = 0;\n    });\n    this.advance();\n    const cancel = () => this.cancelPreparation();\n    signal.addEventListener('abort', cancel, {\n      once: true,\n    });\n    return Promise.all(this.animations.map(animation => animation.finished)).finally(() =>\n      signal.removeEventListener('abort', cancel),\n    );\n  },\n  cancelPreparation() {\n    this.animations?.forEach(animation => animation.cancel());\n  },\n  fail() {\n    this.cancelPreparation();\n  },\n  onBeforeDestroy() {\n    this.cancelPreparation();\n  },\n});\nconst MissionControl = Application.extend({\n  createState() {\n    return {\n      readinessWrites: 0,\n      starts: 0,\n      signal: null,\n    };\n  },\n  async onBeforeStart(app, { loader }, { signal }) {\n    this.getState().signal = signal;\n    try {\n      await loader.prepare(signal);\n      if (signal.aborted) {\n        return;\n      }\n      this.getState().readinessWrites++;\n    } catch (error) {\n      if (signal.aborted) {\n        return;\n      }\n      throw new Error('The antenna fell into the cheese');\n    }\n  },\n  onStart() {\n    this.getState().starts++;\n    this.showView(new FlightDeck());\n  },\n});\nconst StationControls = View.extend({\n  className: 'controls',\n  ui: {\n    open: '#open-station',\n    close: '#close-station',\n    fail: '#fail-preparation',\n    destroy: '#destroy-station',\n    reset: '#reset-station',\n    exploration: '.station-more > summary',\n  },\n  triggers: {\n    'click @ui.open': 'click:open',\n    'click @ui.close': 'click:close',\n    'click @ui.fail': 'click:failPreparation',\n    'click @ui.destroy': 'click:destroy',\n    'click @ui.reset': 'click:reset',\n  },\n  events: {\n    'click @ui.exploration': 'onClickExploration',\n  },\n  onClickExploration() {\n    this.triggerMethod('toggle:exploration', !this.model.exploring);\n  },\n  template: ({ phase, exploring, preparationStep }) => `\n    <button id=\"open-station\" ${['open', 'destroyed'].includes(phase) ? 'disabled' : ''}>${phase === 'open' ? 'Hangar open' : 'Open hangar · ' + preparationStep + '/4'}</button>\n    <details class=\"station-more\" ${exploring ? 'open' : ''}><summary>Explore the whole station’s lifetime</summary>\n    <p class=\"fine\">Compare cancellation with failure. Closing a ready station also destroys its root View and any ship it owns.</p>\n    <button id=\"close-station\" ${['opening', 'open'].includes(phase) ? '' : 'disabled'}>${phase === 'opening' ? 'Cancel opening' : 'Close station'}</button>\n    <button id=\"fail-preparation\" ${phase === 'opening' ? '' : 'disabled'}>Break the antenna</button>\n    <button id=\"destroy-station\" ${phase === 'destroyed' ? 'disabled' : ''}>Destroy station</button></details>\n    <button id=\"reset-station\" ${phase === 'destroyed' ? '' : 'hidden'}>Reset Cheese Patrol</button>`,\n});\nconst MissionChapters = View.extend({\n  className: 'mission-chapters',\n  template: ({ chapter, ready }) => `\n    <button class=\"readiness-chapter\" aria-pressed=\"${chapter === 1}\">1. When may the app appear?</button>\n    <button class=\"flight-chapter\" aria-pressed=\"${chapter === 2}\" ${ready ? '' : 'disabled'}>2. What happens to unfinished work?</button>`,\n  ui: {\n    readiness: '.readiness-chapter',\n    flight: '.flight-chapter',\n  },\n  triggers: {\n    'click @ui.readiness': 'select:readiness',\n    'click @ui.flight': 'select:flight',\n  },\n});\n\nexport { MissionControl, StationLoader, StationControls, MissionChapters };\n"
  }
};
